package email

import (
	"context"
	_ "embed"
	"fmt"
	"html"
	"net/http"
	"strings"
	"time"

	"gymtrack-backend/internal/domain/services"

	resend "github.com/resend/resend-go/v3"
)

// resetPasswordTemplate is the compiled HTML of the React Email template in
// frontend/emails/reset-password.tsx (the reset-password email, scoreboard
// register). Regenerate it with `pnpm email:export` in frontend/ after
// editing the template — do not edit this file's HTML by hand.
//
//go:embed templates/reset_password.html
var resetPasswordTemplate string

// resetURLPlaceholder marks both substitution points (button href and the
// visible fallback URL) in resetPasswordTemplate.
const resetURLPlaceholder = "__RESET_URL__"

// buildResetPasswordHTML injects the escaped reset URL into the embedded
// template. The URL is HTML-escaped so it is safe in both attribute and text
// context.
func buildResetPasswordHTML(resetURL string) string {
	return strings.ReplaceAll(resetPasswordTemplate, resetURLPlaceholder, html.EscapeString(resetURL))
}

// resendAPITimeout bounds a single Resend API call when sent synchronously;
// callers running the send async should also impose their own context deadline.
const resendAPITimeout = 10 * time.Second

// ResendSender implements services.EmailSender using the Resend HTTP API.
type ResendSender struct {
	client   *resend.Client
	fromAddr string // e.g. `GymTrack <noreply@gymtrack.app>`
}

// NewResendSender creates a Resend-backed sender. apiKey must be non-empty.
func NewResendSender(apiKey, fromAddr string) *ResendSender {
	return &ResendSender{
		client:   resend.NewCustomClient(&http.Client{Timeout: resendAPITimeout}, apiKey),
		fromAddr: fromAddr,
	}
}

func (s *ResendSender) SendPasswordResetEmail(ctx context.Context, to, resetURL string) error {
	params := &resend.SendEmailRequest{
		From:    s.fromAddr,
		To:      []string{to},
		Subject: "Reset your GymTrack password",
		Html:    buildResetPasswordHTML(resetURL),
		Text: fmt.Sprintf(
			"Reset your GymTrack password: %s\n\nThis link expires in 1 hour and can only be used once. "+
				"If you did not request a reset, you can safely ignore this email.",
			resetURL,
		),
	}

	if _, err := s.client.Emails.SendWithContext(ctx, params); err != nil {
		return fmt.Errorf("resend send email: %w", err)
	}
	return nil
}

// DisabledSender is a no-op EmailSender used when RESEND_API_KEY is not
// configured (e.g. local development). It records why sending is unavailable.
type DisabledSender struct{}

func (DisabledSender) SendPasswordResetEmail(context.Context, string, string) error {
	return fmt.Errorf("email sending is not configured: set RESEND_API_KEY and EMAIL_FROM")
}

// Compile-time checks that both senders satisfy the domain interface.
var (
	_ services.EmailSender = (*ResendSender)(nil)
	_ services.EmailSender = DisabledSender{}
)
